gateway.subscription.retryCharge(
    subscription.id,
    "24.00",
    true,
    (err, result) => {
        result.success; // true
    }
);

gateway.subscription.retryCharge(
    subscription.id,
    "24.00",
    (err, retryResult) => {
        if (retryResult.success) {
            gateway.transaction.submitForSettlement(
                retryResult.transaction.id,
                (err, result) => {
                    result.success; // true
                }
            );
        }
    }
);

gateway.subscription.retryCharge(
    subscription.id,
    "24.00"
).then(retryResult => {
    if (retryResult.success) {
        gateway.transaction.submitForSettlement(
            retryResult.transaction.id
        ).then(result => {
            result.success; // true
        });
    }
});
